# Гл. 8, пакет G: вариант А (гл. 8 = день 5), G1, G2, новая финальная сцена — сон (память, не харчевня).
import pathlib
p = pathlib.Path("03-manuscript/arc-02/ch-08.md")
t = p.read_text(encoding="utf-8"); n = 0
def rep(old, new, cnt=1):
    global t, n
    c = t.count(old); assert c == cnt, f"count={c} (ожид. {cnt}): {old[:80]!r}"
    t = t.replace(old, new); n += 1

